alter table if exists payment_record add column if not exists query_attempts integer not null default 0;
alter table if exists payment_record add column if not exists last_queried_at timestamptz;
create table if not exists payment_refund (id bigint generated by default as identity primary key, payment_id bigint not null references payment_record(id) on delete restrict, order_id bigint not null references mall_order(id) on delete restrict, refund_no varchar(64) not null unique, refund_amount numeric(18,2) not null, status varchar(20) not null default 'PROCESSING', external_refund_no varchar(100), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists ix_payment_refund_order_status on payment_refund(order_id, status);
create table if not exists payment_reconciliation (id bigint generated by default as identity primary key, trade_date date not null, channel varchar(20) not null default 'WECHAT', status varchar(20) not null default 'PENDING', total_count integer not null default 0, total_amount numeric(18,2) not null default 0, created_at timestamptz not null default now(), unique(trade_date, channel));
